AttackNexusPlan::sub_plan(&self, version, rnd, player, data, _team_plan, _debug) -> SubPlan

// L36
team = player.info.team            // PlayerState+0x930, `assert team < 2`(panic_bounds_check)
pos  = player.info.position       // PlayerState+0x9c0, Position::as_index() 인라인 → 0..4 (Top/Jungle/Mid/Bottom/Support)
cache = data.cache                // OperationData+0x0 → &AbstractGameWithCache
champ = cache.player_champion[team][pos].unwrap()   // cache+0x1e0, None 이면 unwrap_failed 패닉

// L37  MapDef::fountain(team) 인라인 (map_def.rs:234~235)
map = data.context.map            // OperationData+0x8 → GameContext+0x20
(lx, ly, rx, ry) = map.fountains[team]   // MapDef+0x6d70, stride 32, (+0,+8,+0x10,+0x18)

// L38
is_in_heal_area = (champ.x >= lx) && (champ.x <= rx) && (champ.y >= ly) && (champ.y <= ry)
// IR: 먼저 x 범위(uge lx && ule rx) 를 보고, 통과해야 y 범위(ult ly || ugt ry 이면 탈락) 를 본다.
// 즉 '아군 샘(회복지역) 사각형 안에 있는가'.

// L41
if is_in_heal_area {
    if champ.hp < champ.stat_cached.hp {      // Entity+0x670 < Entity+0x628 (= 현재HP < 최대HP)
        return SubPlan::Recall                 // 태그 5, 페이로드 없음
    }
}
// 여기 도달 = (샘 밖) 또는 (샘 안인데 HP 만땅)

// L45  bumpalo Vec::is_empty()/len() 인라인 (vec.rs:1635/1616)
has_enemy_twin_tower = cache.twin_towers[1 - team].len() != 0   // cache+0x130 배열, 원소 stride 32, len @ +0x18

// L47~48
if has_enemy_twin_tower {
    return SubPlan::LineDefense(LineDefenseSubPlan {
        style:              LineStyle::Aggressive,   // ret+0x8 = 0
        line:               self.line,               // ret+0x9 = AttackNexusPlan+0x8 (LineType Top/Mid/Bottom)
        minion_action_type: MinionActionType::Push,  // ret+0xa = 2
    })                                               // 태그 2
}

// L52
return SubPlan::AttackNexus                          // 태그 16, 페이로드 없음

// 반환 태그는 마지막 블록의 phi 로 합류: [5 <- Recall경로] [2 <- LineDefense경로] [16 <- AttackNexus경로],
// store i64 tag, ptr sret+0x0.
// version/rnd/_team_plan/_debug 는 한 번도 읽지 않는다 → 이 함수는 버전 무관·결정적.
